const input = $input.first().json;
const body = input.body || input;

const base64Data = body.file;
const filename = body.filename || 'document';
const source = body.source || 'auto';
const target = body.target || 'fr';

if (!base64Data) {
  throw new Error('No file data provided. Expected base64-encoded file in "file" field.');
}

// Decode base64 to Buffer
const fileBuffer = Buffer.from(base64Data, 'base64');

return [{
  json: {
    filename: filename,
    source: source,
    target: target
  },
  binary: {
    data: {
      data: fileBuffer,
      mimeType: 'application/octet-stream',
      fileName: filename
    }
  }
}];

const item = $input.first();
const binaryData = item.binary ? item.binary.data : null;
const source = item.json.source || 'auto';
const target = item.json.target || 'fr';
const filename = item.json.filename || 'document';
if (!binaryData) { throw new Error('No file binary data found'); }
const fileBuffer = Buffer.from(binaryData.data, 'base64');
const boundary = '----FormBoundary' + Math.random().toString(36).substring(2);
const parts = [];
parts.push(Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="source"\r\n\r\n' + source + '\r\n'));
parts.push(Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="target"\r\n\r\n' + target + '\r\n'));
parts.push(Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="api_key"\r\n\r\n53e04e31-de93-4b49-a0e4-891b1806fc8d\r\n'));
parts.push(Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="file"; filename="' + filename + '"\r\nContent-Type: application/octet-stream\r\n\r\n'));
parts.push(fileBuffer);
parts.push(Buffer.from('\r\n--' + boundary + '--\r\n'));
const body = Buffer.concat(parts);
const response = await this.helpers.httpRequest({ method: 'POST', url: 'https://translate.jefe.ovh/translate_file', headers: { 'Content-Type': 'multipart/form-data; boundary=' + boundary }, body: body, timeout: 120000, returnFullResponse: true });
const statusCode = response.statusCode || response.status || 200;
let responseBody = response.body;
if (typeof responseBody === 'string') { responseBody = JSON.parse(responseBody); }
if (statusCode >= 400) { throw new Error('LibreTranslate error (' + statusCode + '): ' + JSON.stringify(responseBody)); }
return [{ json: { translatedFileUrl: responseBody.translatedFileUrl || '', filename: filename } }];

const item = $input.first();
const binaryData = item.binary?.data;

if (!binaryData) {
  return [{
    json: {
      success: false,
      error: 'No translated file received'
    }
  }];
}

// Get the binary buffer
const buffer = Buffer.from(binaryData.data, 'base64');
const base64Content = buffer.toString('base64');

// Get filename from translate response
const translateResponse = $('Translate File').item.json;
const originalUrl = translateResponse.translatedFileUrl || '';
const translatedFilename = originalUrl.split('/').pop() || 'translated.txt';

return [{
  json: {
    success: true,
    filename: translatedFilename,
    file: base64Content
  }
}];

